#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <cassert>
#include <iostream>
enum class Action { None, Tap, Charged };
// 방향 입력 없이 버튼의 상태와 경과 tick만 읽는다.
class OneButton {
    bool wasHeld_ = false;
    int charge_ = 0;
public:
    Action sample(bool held) {
        if (held) {
            if (!wasHeld_) charge_=1;
            else if(charge_<3) ++charge_;
            wasHeld_=true;
            return Action::None;
        }
        if(!wasHeld_) return Action::None;
        const Action result=charge_>=2?Action::Charged:Action::Tap;
        wasHeld_=false;charge_=0;return result;
    }
    void cancel() { wasHeld_=false;charge_=0; }
};
int main(){
    OneButton b;assert(b.sample(false)==Action::None);
    assert(b.sample(true)==Action::None);
    assert(b.sample(false)==Action::Tap);
    assert(b.sample(false)==Action::None);
    b.sample(true);b.sample(true);
    assert(b.sample(false)==Action::Charged);
    for(int i=0;i<10000;++i)assert(b.sample(true)==Action::None);
    assert(b.sample(false)==Action::Charged);
    b.sample(true);b.cancel();assert(b.sample(false)==Action::None);
    b.sample(true);assert(b.sample(false)==Action::Tap);
    std::cout<<"one-button tests passed\n";
}
